import (
	context "context"
	fern "github.com/go-union-base-properties/fern"
	fernclient "github.com/go-union-base-properties/fern/client"
)

client := fernclient.NewClient()
response, err := client.Create(
	context.TODO(),
	&fern.Shape{
		Circle: &fern.Circle{
			ID: "shape-1",
			CreatedAt: fern.String(
				"2024-01-01T00:00:00Z",
			),
			Radius: 1.5,
		},
	},
)
